import { useState } from 'react';
import { JxToggle, JxSlider, JxSwitch, JxDivider, JxSelect, JxBadge } from '@jinx-ui/react';

type ThemeValue = 'system' | 'light' | 'dark';

export interface AppearanceSettings {
  theme: ThemeValue;
  scale: number;
  dense: boolean;
  font: string;
}

interface AppearanceSettingsScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_LABELS: Record<ThemeValue, string> = {
  system: 'Системная',
  light: 'Светлая',
  dark: 'Тёмная',
};

export default function AppearanceSettingsScreen({ onChange }: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState<ThemeValue>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState('sans');

  const emit = (next: Partial<AppearanceSettings>) => {
    onChange?.({ theme, scale, dense, font, ...next });
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24, maxWidth: 420 }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <h1
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            color: 'var(--jx-text)',
            fontSize: 22,
          }}
        >
          Внешний вид
        </h1>
        <JxBadge tone="accent">{THEME_LABELS[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <span style={{ color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-sans)', fontSize: 13 }}>
          Тема
        </span>
        <JxToggle
          items={[
            { value: 'system', label: 'Системная' },
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
          ]}
          value={theme}
          onValueChange={(value) => {
            const next = value as ThemeValue;
            setTheme(next);
            emit({ theme: next });
          }}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={1}
        unit="%"
        showOutput
        value={scale}
        onValueChange={(value) => {
          setScale(value);
          emit({ scale: value });
        }}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => {
          const next = event.target.checked;
          setDense(next);
          emit({ dense: next });
        }}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'sans', label: 'Sans (по умолчанию)' },
          { value: 'display', label: 'Serif (заголовки)' },
          { value: 'mono', label: 'Mono' },
        ]}
        value={font}
        onValueChange={(value) => {
          setFont(value);
          emit({ font: value });
        }}
      />
    </div>
  );
}

